<script setup>import{ref}from'vue';import{useRouter}from'vue-router';import api from'../services/api';import{setAuth}from'../stores';const name=ref(''),email=ref(''),password=ref(''),role=ref('customer'),error=ref(''),router=useRouter();async function submit(){try{const r=await api.post('/auth/register',{name:name.value,email:email.value,password:password.value,role:role.value});setAuth(r.data.user,r.data.token);router.push('/shop')}catch(e){error.value=e.response?.data?.message||'Registration failed'}}}</script><template><div class="flex min-h-screen items-center justify-center bg-slate-950 p-4"><form @submit.prevent="submit" class="w-full max-w-md rounded-3xl bg-white p-8"><RouterLink to="/shop" class="text-xl font-black">Market<span class="text-indigo-600">Flow</span></RouterLink><h1 class="mt-8 text-3xl font-black">Create account</h1><input v-model="name" required placeholder="Full name" class="mt-6 w-full rounded-xl border p-3"/><input v-model="email" type="email" required placeholder="Email" class="mt-3 w-full rounded-xl border p-3"/><input v-model="password" type="password" required placeholder="Password" class="mt-3 w-full rounded-xl border p-3"/><select v-model="role" class="mt-3 w-full rounded-xl border p-3"><option value="customer">Customer</option><option value="affiliate">Affiliate</option></select><button class="mt-5 w-full rounded-xl bg-indigo-600 py-3 font-bold text-white">Create account</button></form></div></template>